output:
220	                "[vela_tls] Pool slot %d still in use at shutdown, skipping\n", i);
221	            continue;
222	        }
223	        if (s_pool[i].valid) {
224	            tls_ctx_free(&s_pool[i].ctx);
225	            s_pool[i].valid = false;
226	        }
227	        s_pool[i].host[0] = '\0';
228	    }
229	    pthread_mutex_unlock(&s_pool_lock);
230	}
