64	int tool_analyze_image_execute(const char* input_json, char* output, size_t output_size)
65	{
66	    const char* image_path = AGENT_CAPTURE_PATH;
67	    const char* prompt = NULL;
68	    bool need_capture = true;
69	
70	    /* Parse input: {"image_path": "...", "prompt": "..."} */
71	    cJSON* root = cJSON_Parse(input_json);
72	    if (root) {
73	        cJSON* p = cJSON_GetObjectItem(root, "image_path");
74	        if (p && cJSON_IsString(p) && p->valuestring[0]) {
75	            image_path = p->valuestring;
76	            need_capture = false;
77	        }
78	        cJSON* q = cJSON_GetObjectItem(root, "prompt");
79	        if (q && cJSON_IsString(q) && q->valuestring[0])
80	            prompt = q->valuestring;
81	    }
82	
83	    /* Auto-capture screen if using default path */
84	    if (need_capture) {
85	        if (auto_capture(image_path) != OK) {
86	            snprintf(output, output_size,
87	                "{\"error\":\"fbcapture failed, is display active?\"}");
88	            cJSON_Delete(root);
89	            return ERROR;
90	        }
91	    }
92	
93	    /* Read image file */
94	    FILE* fp = fopen(image_path, "rb");
95	    if (!fp) {
96	        snprintf(output, output_size, "{\"error\":\"Cannot open image: %s\"}", image_path);
97	        cJSON_Delete(root);
98	        return ERROR;
99	    }
100	
101	    struct stat st;
102	    if (stat(image_path, &st) != 0 || st.st_size <= 0) {
103	        fclose(fp);
104	        snprintf(output, output_size, "{\"error\":\"Cannot stat image: %s\"}", image_path);
105	        cJSON_Delete(root);
106	        return ERROR;
107	    }
108	
109	    if ((size_t)st.st_size > AGENT_VISION_MAX_IMAGE_SIZE) {
110	        fclose(fp);
111	        snprintf(output, output_size,
112	            "{\"error\":\"Image too large (%ld bytes, max %d)\"}",
113	            (long)st.st_size, AGENT_VISION_MAX_IMAGE_SIZE);
114	        cJSON_Delete(root);
115	        return ERROR;
116	    }
117	
118	    unsigned char* raw = malloc((size_t)st.st_size);
119	    if (!raw) {
120	        fclose(fp);
121	        snprintf(output, output_size, "{\"error\":\"OOM reading image\"}");
122	        cJSON_Delete(root);
123	        return ERROR;
124	    }
125	
126	    size_t nread = fread(raw, 1, (size_t)st.st_size, fp);
127	    fclose(fp);
128	
129	    if (nread != (size_t)st.st_size) {
130	        free(raw);
131	        snprintf(output, output_size, "{\"error\":\"Short read on image\"}");
132	        cJSON_Delete(root);
133	        return ERROR;
134	    }
135	
136	    /* Detect image format from magic bytes */
137	    const char* mime_type = "image/jpeg";
138	    if (nread >= 4 && raw[0] == 0x89 && raw[1] == 'P'
139	        && raw[2] == 'N' && raw[3] == 'G')
140	        mime_type = "image/png";
141	    else if (nread >= 4 && !memcmp(raw, "GIF8", 4))
142	        mime_type = "image/gif";
143	    else if (nread >= 12 && !memcmp(raw, "RIFF", 4) && !memcmp(raw + 8, "WEBP", 4))
144	        mime_type = "image/webp";
145	
146	    syslog(LOG_INFO, "[%s] Image %s: %ld bytes (%s)\n",
147	        TAG, image_path, (long)nread, mime_type);
148	
149	    size_t b64_len = ((nread + 2) / 3) * 4;
150	    if (b64_len > AGENT_VISION_MAX_B64_SIZE) {
151	        free(raw);
152	        snprintf(output, output_size, "{\"error\":\"Base64 too large\"}");
153	        cJSON_Delete(root);
154	        return ERROR;
155	    }
156	
157	    char* b64 = malloc(b64_len + 1);
158	    if (!b64) {
159	        free(raw);
160	        snprintf(output, output_size, "{\"error\":\"OOM for base64\"}");
161	        cJSON_Delete(root);
162	        return ERROR;
163	    }
164	
165	    size_t written = 0;
166	    mbedtls_base64_encode((unsigned char*)b64, b64_len, &written, raw, nread);
167	    b64[written] = '\0';
168	
169	    syslog(LOG_INFO, "[%s] Image %s: %ld bytes -> %d b64 chars (%s)\n",
170	        TAG, image_path, (long)nread, (int)written, mime_type);
171	
172	    /* Call vision LLM */
173	    char* resp_buf = calloc(1, output_size);
174	    if (!resp_buf) {
175	        free(raw);
176	        free(b64);
177	        snprintf(output, output_size, "{\"error\":\"OOM for response\"}");
178	        cJSON_Delete(root);
179	        return ERROR;
180	    }
181	
182	    int ret = llm_chat_vision_raw(prompt, raw, nread, mime_type,
183	        resp_buf, output_size);
184	    free(raw);
185	    free(b64);
186	    cJSON_Delete(root);
187	
188	    if (ret != OK) {
189	        snprintf(output, output_size, "{\"error\":\"%s\"}", resp_buf);
190	        free(resp_buf);
191	        return ret;
192	    }
193	
194	    /* Return as JSON */
195	    cJSON* result = cJSON_CreateObject();
196	    cJSON_AddStringToObject(result, "analysis", resp_buf);
197	    free(resp_buf);
198	
199	    char* json_str = cJSON_PrintUnformatted(result);
200	    cJSON_Delete(result);
201	
202	    if (json_str) {
203	        strncpy(output, json_str, output_size - 1);
204	        output[output_size - 1] = '\0';
205	        syslog(LOG_INFO, "[%s] Analysis complete: %d bytes\n", TAG, (int)strlen(output));
206	        free(json_str);
207	    }
208	
209	    return OK;
210	}
