47	static int ensure_dir(const char *path)
48	{
49	    struct stat st = {0};
50	    if (stat(path, &st) == -1) {
51	        /* Try to create parent first */
52	        char parent[256];
53	        strncpy(parent, path, sizeof(parent) - 1);
54	        char *slash = strrchr(parent, '/');
55	        if (slash && slash != parent) {
56	            *slash = '\0';
57	            if (ensure_dir(parent) != OK) return ERROR;
58	        }
59	        
60	        if (mkdir(path, 0755) == -1) {
61	            syslog(LOG_ERR, "[%s] mkdir failed for %s, errno=%d\n", TAG, path, errno);
62	            return ERROR;
63	        }
64	        syslog(LOG_INFO, "[%s] Created directory: %s\n", TAG, path);
65	    }
66	    return OK;
67	}
