57	static cJSON *load_json(void)
58	{
59	    FILE *f = fopen(AGENT_CONFIG_FILE, "r");
60	    if (!f) return cJSON_CreateObject();
61	
62	    fseek(f, 0, SEEK_END);
63	    long sz = ftell(f);
64	    fseek(f, 0, SEEK_SET);
65	
66	    if (sz <= 0) { fclose(f); return cJSON_CreateObject(); }
67	
68	    char *buf = (char *)malloc((size_t)(sz + 1));
69	    if (!buf) { fclose(f); return cJSON_CreateObject(); }
70	
71	    size_t n = fread(buf, 1, (size_t)sz, f);
72	    buf[n] = '\0';
73	    fclose(f);
74	
75	    cJSON *root = cJSON_Parse(buf);
76	    free(buf);
77	    return root ? root : cJSON_CreateObject();
78	}
79	
80	static int save_json(cJSON *root)
81	{
82	    char *str = cJSON_PrintUnformatted(root);
83	    if (!str) return ERROR;
84	
85	    /* Use open() with explicit 0600 to ensure config file is owner-only.
86	     * fopen("w") inherits umask which may be too permissive. */
87	    int fd = open(AGENT_CONFIG_FILE,
88	                  O_WRONLY | O_CREAT | O_TRUNC, 0600);
89	    if (fd < 0) { free(str); return ERROR; }
90	
91	    FILE *f = fdopen(fd, "w");
92	    if (!f) { close(fd); free(str); return ERROR; }
93	    fputs(str, f);
94	    fclose(f);
95	    free(str);
96	    return OK;
97	}
98	
99	/* ── public API ──────────────────────────────────────────────── */
100	
101	int config_store_init(void)
102	{
103	    mkdirs(AGENT_DATA_DIR);
104	    mkdirs(AGENT_CONFIG_DIR);
105	    mkdirs(AGENT_MEMORY_DIR);
106	    mkdirs(AGENT_SESSION_DIR);
107	    syslog(LOG_INFO, "[%s] Config store ready at %s\n", TAG, AGENT_CONFIG_FILE);
108	    return OK;
109	}
110	
111	int claw_config_get(const char *key, char *buf, size_t buf_size)
112	{
113	    pthread_mutex_lock(&s_lock);
114	    cJSON *root = load_json();
115	    cJSON *item = cJSON_GetObjectItem(root, key);
116	    int ret = ERROR;
117	    if (item && cJSON_IsString(item) && item->valuestring[0] != '\0') {
118	        strncpy(buf, item->valuestring, buf_size - 1);
119	        buf[buf_size - 1] = '\0';
120	        ret = OK;
121	    }
122	    cJSON_Delete(root);
123	    pthread_mutex_unlock(&s_lock);
124	    return ret;
125	}
126	
127	int claw_config_set(const char *key, const char *value)
128	{
129	    pthread_mutex_lock(&s_lock);
130	    cJSON *root = load_json();
131	    cJSON_DeleteItemFromObject(root, key);
132	    cJSON_AddStringToObject(root, key, value);
133	    int ret = save_json(root);
134	    cJSON_Delete(root);
135	    pthread_mutex_unlock(&s_lock);
136	    return ret;
137	}
138	
139	int config_del(const char *key)
140	{
141	    pthread_mutex_lock(&s_lock);
142	    cJSON *root = load_json();
143	    cJSON_DeleteItemFromObject(root, key);
144	    int ret = save_json(root);
145	    cJSON_Delete(root);
146	    pthread_mutex_unlock(&s_lock);
147	    return ret;
148	}
149	
150	int config_erase_all(void)
151	{
152	    pthread_mutex_lock(&s_lock);
153	    cJSON *empty = cJSON_CreateObject();
154	    int ret = save_json(empty);
155	    cJSON_Delete(empty);
156	    pthread_mutex_unlock(&s_lock);
157	    return ret;
158	}
